SELECT table_name, column_name, data_default FROM xmltable('ROWSET/ROW'
    passing dbms_xmlgen.getxmltype('SELECT table_name, column_name, data_default FROM user_tab_columns')
    columns table_name      VARCHAR2(128)   PATH '*[1]'
            , column_name   VARCHAR2(128)   PATH '*[2]'
            , data_default  VARCHAR2(2000)  PATH '*[3]'
            );

CREATE TABLE t (
  a INT PRIMARY KEY USING INDEX TABLESPACE "pg_default" DEFERRABLE INITIALLY DEFERRED
)

CREATE TABLE t (
  a INT PRIMARY KEY USING INDEX TABLESPACE pg_default
)

CREATE TABLE t (
  a INT PRIMARY KEY WITH (fillfactor=70) USING INDEX TABLESPACE pg_default
)

CREATE TABLE t (
  a INT UNIQUE NULLS NOT DISTINCT WITH (fillfactor=70) USING INDEX TABLESPACE pg_default
)

CREATE TABLE t (
  a INT UNIQUE USING INDEX TABLESPACE "pg_default" DEFERRABLE
)

CREATE TABLE t (
  a INT,
  UNIQUE (
    a
  ) USING INDEX TABLESPACE pg_default
)
